export type SubscriptionId = string;

/**  Palette colour of a room tag. */
export type TagColour = "grey" | "red" | "orange" | "amber" | "green" | "teal" | "blue" | "violet" | "pink";

export type ThreadSummary = {
	root_event_id: EventId,
	reply_count: number,
	latest_reply_timestamp: number,
};

export type TimelineItemContent = { kind: "TextMessage"; data: {
	body: string,
	formatted_body: string | null,
	html_sanitized: boolean,
} } | { kind: "Media"; data: {
	/**  `mxc://` URI for plain media, or a JSON-encoded encrypted source (starts with `{`). */
	uri: string,
	mime_type: string,
	size_bytes: number,
	thumbnail_uri: string | null,
	/**  Caption or file name. */
	body?: string,
	/**  `image`, `video`, `audio`, `file` or `sticker`. */
	media_kind?: string,
	width?: number | null,
	height?: number | null,
	duration_ms?: number | null,
} } | { kind: "Reaction"; data: {
	key: string,
	count: number,
	senders: UserId[],
} } | { kind: "Poll"; data: {
	question: string,
	answers: PollAnswerDto[],
	disclosed: boolean,
	max_selections: number,
	total_votes: number,
	has_ended: boolean,
	end_time: number | null,
	my_votes: string[],
} } | { kind: "CallInvite"; data: {
	call_id: string,
	is_video: boolean,
} } | { kind: "Redacted" } | { kind: "RoomState"; data: {
	state_type: string,
	content_json: string,
} } | { kind: "DayDivider"; data: {
	timestamp_millis: number,
} } | { kind: "Virtual" } | { kind: "UnableToDecrypt"; data: {
	reason: string,
} };

export type TimelineItemDto = {
	internal_id: string,
	event_id: EventId | null,
	sender: UserId,
	timestamp_millis: number,
	content: TimelineItemContent,
	send_state: EventSendState,
	is_own: boolean,
	reply_to: TimelineItemDto | null,
	thread_summary: ThreadSummary | null,
	read_receipts: UserId[] | null,
	sender_display_name?: string | null,
	sender_avatar_url?: string | null,
	edited?: boolean,
	reactions?: ReactionSummary[],
	/**  Transaction id for local echoes (use with RetrySend/CancelSend). */
	transaction_id?: string | null,
};

export type TimelineItemPreview = {
	sender: UserId,
	timestamp_millis: number,
	body: string,
};

/**
 *  Open Graph summary of a link, as the homeserver reports it. Every field is optional: a page may not
 *  declare it, and the image is an `mxc://` URI that is fetched through `GetMedia`.
 */
export type UrlPreviewDto = {
	url: string,
	title: string | null,
	description: string | null,
	site_name: string | null,
	image: string | null,
	image_width: number | null,
	image_height: number | null,
};

export type UserId = string;

/**  Profile of one user, optionally as seen in a room. */
export type UserProfileDto = {
	user_id: UserId,
	display_name: string | null,
	/**  `mxc://` avatar URI, fetch it with `GetMedia`. */
	avatar_url: string | null,
	/**  `join`, `invite`, `leave`, `ban` or `knock` in the given room, if a room was given. */
	membership: string | null,
	power_level: number | null,
	/**  An existing direct-message room with this user. */
	dm_room_id: RoomId | null,
	is_me: boolean,
};

export type VectorDiffDto<T> = { type: "Append"; content: {
	values: T[],
} } | { type: "Clear" } | { type: "PushFront"; content: {
	value: T,
} } | { type: "PushBack"; content: {
	value: T,
} } | { type: "PopFront" } | { type: "PopBack" } | { type: "Insert"; content: {
	index: number,
	value: T,
} } | { type: "Set"; content: {
	index: number,
	value: T,
} } | { type: "Remove"; content: {
	index: number,
} } | { type: "Truncate"; content: {
	length: number,
} } | { type: "Reset"; content: {
	values: T[],
} };

export type VerificationState = "Ready" | "WaitingForPartner" | ({ CompareEmojis: {
	emojis: SasEmoji[],
	decimal_1: number,
	decimal_2: number,
	decimal_3: number,
} }) & { Cancelled?: never } | "Verified" | ({ Cancelled: {
	reason: string,
} }) & { CompareEmojis?: never };
